using System.Linq;
using UnityEngine;
public static class InspectMudStamp {
public static string Main(){var soils=Object.FindObjectsByType<SoftGroundRuts>().Where(s=>s.enabled&&s.profile!=null&&s.persistentId!=null&&s.persistentId.StartsWith("main0")).ToArray();var root=soils[0].transform.parent;var ray=new Ray(root.position+root.right*.7f+Vector3.up*10,Vector3.down);RaycastHit best=default;bool found=false;foreach(var s in soils)if(s.GetComponent<MeshCollider>().Raycast(ray,out var hit,20)&&(!found||hit.point.y>best.point.y)){best=hit;found=true;}if(!found)return "no hit";var soil=best.collider.GetComponent<SoftGroundRuts>();var p=best.point;var filter=soil.GetComponent<MeshFilter>();var nearest=filter.sharedMesh.vertices.OrderBy(v=>{var w=soil.transform.TransformPoint(v);return new Vector2(w.x-p.x,w.z-p.z).sqrMagnitude;}).Take(4).ToArray();string report="hit="+soil.name+" pos="+p+" local="+soil.transform.InverseTransformPoint(p)+" half="+soil.fieldHalfSize+" bounds="+soil.GetComponent<Renderer>().bounds+" enabled="+soil.enabled+" profile="+soil.profile.name+" near="+string.Join(";",nearest.Select(x=>x.ToString("F3")))+" depth="+soil.DepthAt(p);soil.Dig(p,1,2);soil.Commit();report+=" direct="+soil.DepthAt(p);SoftGroundRuts.Contact(p,root.forward,.285f,5000,15,1,2);foreach(var s in soils)s.Commit();report+=" contact="+soil.DepthAt(p);return report;}}
